-- Dijital Tabağım - Tarif Derlemesi (10 tarif)
-- Kaynak: "Tarif Derlemesi – 10 Tarif.pdf" (6 Kasım 2026)
-- Supabase Dashboard > SQL Editor'de bu dosyayı çalıştırın.
--
-- 1) recipes tablosuna ayrıntı sütunları eklenir.
-- 2) Listede adı geçen tarifler güncellenir (id korunur → favoriler kalır),
--    olmayanlar eklenir.
-- 3) Listede OLMAYAN eski örnek tarifler silinir (favori kayıtları da silinir).
--
-- Bu dosya scripts ile üretilmiştir; elle düzenlerken tek tırnakları ('') çift yazın.

BEGIN;

ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS description      TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS region           TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS servings         TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS prep_time        TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS cook_time        TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS tips             TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS nutrition_advice TEXT;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS dietitian_note   TEXT;
-- [{"ad": "Enerji", "miktar": "~200 kcal"}, ...] — sıra korunur
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS nutrition        JSONB;
ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS nutrition_total  JSONB;

-- Listede olmayan eski tarifleri kaldır
DELETE FROM public.recipes WHERE name NOT IN ('Ezogelin Çorbası', 'Hünkâr Beğendi', 'Zeytinyağlı Taze Fasulye', 'Hamsili Pilav', 'Kısır', 'Kayseri Mantısı', 'Menemen', 'Tepsi Kebabı', 'Ayran Aşı Çorbası', 'Fırın Sütlaç');

-- 1. Ezogelin Çorbası
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Çorba',
  duration = '55 dk',
  rating = NULL,
  ingredients = ARRAY['1 su bardağı kırmızı mercimek (yaklaşık 180 g)', '¼ su bardağı pirinç', '¼ su bardağı ince bulgur', '1 adet orta boy kuru soğan', '2 yemek kaşığı tereyağı', '1 yemek kaşığı domates salçası', '1 yemek kaşığı biber salçası', '1 çay kaşığı kuru nane', '1 çay kaşığı pul biber', '1 çay kaşığı tuz', '7 su bardağı sıcak su', '1 adet limon (servis için)']::text[],
  instructions = ARRAY['Mercimek, pirinç ve bulguru bol suda yıkayıp süzün.', 'Tencerede tereyağını eritin, ince doğranmış soğanı pembeleşene kadar kavurun (yaklaşık 4 dakika).', 'Domates ve biber salçasını ekleyip kokusu çıkana kadar 1–2 dakika kavurun.', 'Mercimek, pirinç ve bulguru ekleyip karıştırın, ardından sıcak suyu ilave edin.', 'Kaynamaya başlayınca altını kısın. Ara ara karıştırarak mercimekler dağılana kadar pişirin (yaklaşık 35 dakika). Çorba fazla koyulaşırsa az miktarda sıcak su ekleyin.', 'Tuz, kuru nane ve pul biberi ekleyip 5 dakika daha pişirin.', 'Limon dilimleriyle birlikte sıcak servis edin.']::text[],
  description = 'Kırmızı mercimek, pirinç ve bulgurla pişirilen, naneli ve pul biberli geleneksel çorba',
  region = 'Güneydoğu Anadolu – Gaziantep',
  servings = '6 kişilik',
  prep_time = '10 dakika',
  cook_time = '45 dakika',
  tips = 'Ezogelin geleneksel olarak blenderdan geçirilmez; bulgur ve pirinç taneleri çorbaya kıvam verir. Nane ve pul biber, servisten önce tereyağında kızdırılıp üzerine de gezdirilebilir.',
  nutrition_advice = 'Yanında tam tahıllı ekmek ve mevsim salatası ile hafif bir akşam öğünü oluşturur. Bir dilim peynir veya yoğurtla protein içeriği artırılabilir.',
  dietitian_note = 'Kırmızı mercimek iyi bir bitkisel protein ve lif kaynağıdır; bulgurla birlikte tokluk süresini uzatır. Baklagil ile tahılın bir arada kullanılması, bitkisel proteinlerin amino asit dengesini iyileştirir. Tereyağı miktarının yarısı zeytinyağıyla değiştirilerek doymuş yağ oranı azaltılabilir. Tuz, servis öncesi tadına bakılarak ayarlanmalıdır.',
  nutrition = '[{"ad": "Enerji", "miktar": "~200 kcal"}, {"ad": "Protein", "miktar": "~9 g"}, {"ad": "Yağ", "miktar": "~5 g"}, {"ad": "Karbonhidrat", "miktar": "~32 g"}, {"ad": "Lif", "miktar": "~5 g"}, {"ad": "Şeker", "miktar": "~2 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~1200 kcal"}, {"ad": "Protein", "miktar": "~53 g"}, {"ad": "Yağ", "miktar": "~28 g"}, {"ad": "Karbonhidrat", "miktar": "~194 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '0 minutes'
WHERE name = 'Ezogelin Çorbası';
