SELECT 'Ezogelin Çorbası', NULL, 'Çorba', '55 dk', NULL, ARRAY['1 su bardağı kırmızı mercimek (yaklaşık 180 g)', '¼ su bardağı pirinç', '¼ su bardağı ince bulgur', '1 adet orta boy kuru soğan', '2 yemek kaşığı tereyağı', '1 yemek kaşığı domates salçası', '1 yemek kaşığı biber salçası', '1 çay kaşığı kuru nane', '1 çay kaşığı pul biber', '1 çay kaşığı tuz', '7 su bardağı sıcak su', '1 adet limon (servis için)']::text[], ARRAY['Mercimek, pirinç ve bulguru bol suda yıkayıp süzün.', 'Tencerede tereyağını eritin, ince doğranmış soğanı pembeleşene kadar kavurun (yaklaşık 4 dakika).', 'Domates ve biber salçasını ekleyip kokusu çıkana kadar 1–2 dakika kavurun.', 'Mercimek, pirinç ve bulguru ekleyip karıştırın, ardından sıcak suyu ilave edin.', 'Kaynamaya başlayınca altını kısın. Ara ara karıştırarak mercimekler dağılana kadar pişirin (yaklaşık 35 dakika). Çorba fazla koyulaşırsa az miktarda sıcak su ekleyin.', 'Tuz, kuru nane ve pul biberi ekleyip 5 dakika daha pişirin.', 'Limon dilimleriyle birlikte sıcak servis edin.']::text[], 'Kırmızı mercimek, pirinç ve bulgurla pişirilen, naneli ve pul biberli geleneksel çorba', 'Güneydoğu Anadolu – Gaziantep', '6 kişilik', '10 dakika', '45 dakika', 'Ezogelin geleneksel olarak blenderdan geçirilmez; bulgur ve pirinç taneleri çorbaya kıvam verir. Nane ve pul biber, servisten önce tereyağında kızdırılıp üzerine de gezdirilebilir.', 'Yanında tam tahıllı ekmek ve mevsim salatası ile hafif bir akşam öğünü oluşturur. Bir dilim peynir veya yoğurtla protein içeriği artırılabilir.', 'Kırmızı mercimek iyi bir bitkisel protein ve lif kaynağıdır; bulgurla birlikte tokluk süresini uzatır. Baklagil ile tahılın bir arada kullanılması, bitkisel proteinlerin amino asit dengesini iyileştirir. Tereyağı miktarının yarısı zeytinyağıyla değiştirilerek doymuş yağ oranı azaltılabilir. Tuz, servis öncesi tadına bakılarak ayarlanmalıdır.', '[{"ad": "Enerji", "miktar": "~200 kcal"}, {"ad": "Protein", "miktar": "~9 g"}, {"ad": "Yağ", "miktar": "~5 g"}, {"ad": "Karbonhidrat", "miktar": "~32 g"}, {"ad": "Lif", "miktar": "~5 g"}, {"ad": "Şeker", "miktar": "~2 g"}]'::jsonb, '[{"ad": "Enerji", "miktar": "~1200 kcal"}, {"ad": "Protein", "miktar": "~53 g"}, {"ad": "Yağ", "miktar": "~28 g"}, {"ad": "Karbonhidrat", "miktar": "~194 g"}]'::jsonb, NOW() - INTERVAL '0 minutes'
WHERE NOT EXISTS (SELECT 1 FROM public.recipes WHERE name = 'Ezogelin Çorbası');

-- 2. Hünkâr Beğendi
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Ana Yemek',
  duration = '1 sa 20 dk',
  rating = NULL,
  ingredients = ARRAY['Et için:', '500 g kuşbaşı kuzu eti (dana eti de kullanılabilir)', '1 adet orta boy kuru soğan', '2 adet orta boy domates', '1 yemek kaşığı domates salçası', '2 adet sivri biber', '2 yemek kaşığı sıvı yağ', '1 çay kaşığı tuz', '0,5 çay kaşığı karabiber', '1 çay kaşığı kekik', '1,5 su bardağı sıcak su', 'Beğendi için:', '4 adet orta boy patlıcan (yaklaşık 1 kg)', '2 yemek kaşığı tereyağı', '2 yemek kaşığı un', '1,5 su bardağı süt', '50 g rendelenmiş kaşar peyniri', '0,5 çay kaşığı tuz', '1 tutam muskat']::text[],
  instructions = ARRAY['Kuşbaşı eti tencereye alın, kapağı kapalı şekilde suyunu salıp çekene kadar orta ateşte pişirin (yaklaşık 10 dakika).', 'Sıvı yağı ve yemeklik doğranmış soğanı ekleyip soğanlar pembeleşene kadar kavurun.', 'Domates salçasını ekleyip 1 dakika kavurun. Rendelenmiş domatesleri ve doğranmış sivri biberleri ilave edin.', 'Sıcak suyu, tuzu, karabiberi ve kekiki ekleyin. Kapağı kapalı, kısık ateşte et yumuşayana kadar pişirin (yaklaşık 45 dakika).', 'Et pişerken patlıcanları ocak ateşinde veya fırında (220°C) kabukları kararana kadar közleyin (yaklaşık 25 dakika). Kabuklarını soyup bıçakla ince kıyın.', 'Ayrı bir tencerede tereyağını eritin, unu ekleyip kokusu çıkana kadar 2–3 dakika kavurun.', 'Ilık sütü azar azar ekleyerek topaklanmaması için sürekli çırpın ve koyu bir sos elde edin.', 'Kıyılmış patlıcanı sosa ekleyip 5 dakika karıştırarak pişirin. Kaşar, tuz ve muskatı ekleyin; kaşar eriyene kadar karıştırın.', 'Beğendiyi servis tabağına yayın, ortasına sıcak eti yerleştirip hemen servis edin.']::text[],
  description = 'Közlenmiş patlıcan ve kaşarla hazırlanan beyaz soslu beğendi üzerinde domatesli kuzu yahnisi',
  region = 'Marmara – İstanbul (Osmanlı saray mutfağı)',
  servings = '4 kişilik',
  prep_time = '20 dakika',
  cook_time = '60 dakika',
  tips = 'Közlenen patlıcanların acısını almak için soyduktan sonra birkaç damla limonlu suda bekletip sıkmak rengin açık kalmasını sağlar. Geleneksel tarifte et için kuzu kullanılır.',
  nutrition_advice = 'Yanında bol yeşilliğe sahip bir çoban salatası ile servis edilmesi önerilir. Yemek doyurucu olduğundan ayrıca pilav eklenmemesi öğünü dengeler.',
  dietitian_note = 'Kuzu eti yüksek kaliteli protein, demir ve B12 vitamini açısından zengindir; süt ve kaşar kalsiyum katkısı sağlar. Tereyağı, kaşar ve yağlı et nedeniyle doymuş yağ içeriği yüksektir. Yağı alınmış et, yarım yağlı süt ve daha az kaşar tercih edilerek enerji değeri düşürülebilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~535 kcal"}, {"ad": "Protein", "miktar": "~33 g"}, {"ad": "Yağ", "miktar": "~36 g"}, {"ad": "Karbonhidrat", "miktar": "~22 g"}, {"ad": "Lif", "miktar": "~6 g"}, {"ad": "Şeker", "miktar": "~12 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~2140 kcal"}, {"ad": "Protein", "miktar": "~130 g"}, {"ad": "Yağ", "miktar": "~145 g"}, {"ad": "Karbonhidrat", "miktar": "~89 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '1 minutes'
WHERE name = 'Hünkâr Beğendi';
