WHERE NOT EXISTS (SELECT 1 FROM public.recipes WHERE name = 'Hünkâr Beğendi');

-- 3. Zeytinyağlı Taze Fasulye
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Zeytinyağlı',
  duration = '1 sa 5 dk',
  rating = NULL,
  ingredients = ARRAY['750 g taze fasulye (ayşe kadın)', '2 adet orta boy kuru soğan', '2 adet orta boy olgun domates', '3 diş sarımsak', '⅓ su bardağı zeytinyağı', '1 çay kaşığı toz şeker', '1,5 çay kaşığı tuz', '1 su bardağı sıcak su']::text[],
  instructions = ARRAY['Fasulyelerin uçlarını ve kılçıklarını ayıklayın, yıkayıp 2–3 parçaya bölün.', 'Tencerede zeytinyağını ısıtın. Piyazlık doğranmış soğanı ve ince dilimlenmiş sarımsağı renk almadan 3–4 dakika kavurun.', 'Fasulyeleri ekleyin, kapağı kapalı şekilde ara ara karıştırarak 10 dakika çevirin.', 'Rendelenmiş domatesleri, toz şekeri ve tuzu ekleyip karıştırın. Sıcak suyu ilave edin.', 'Kapağı kapalı, kısık ateşte fasulyeler iyice yumuşayana kadar pişirin (yaklaşık 35 dakika).', 'Ocağı kapatın ve yemeği tencerede soğumaya bırakın. Oda sıcaklığında veya soğuk servis edin.']::text[],
  description = 'Domates ve soğanla kısık ateşte pişirilen, soğuk servis edilen zeytinyağlı ayşe kadın fasulye',
  region = 'Ege',
  servings = '4 kişilik',
  prep_time = '20 dakika',
  cook_time = '45 dakika',
  tips = 'Zeytinyağlılar tencerede soğutulduğunda suyunu çeker ve lezzeti oturur. Şeker, domatesin ekşiliğini dengelemek içindir; tatlı domates kullanılıyorsa çıkarılabilir.',
  nutrition_advice = 'Yanında yoğurt ve tam tahıllı ekmekle hafif bir ana öğün olur. Et veya tavuk yemeği yanında sebze garnitürü olarak da servis edilebilir.',
  dietitian_note = 'Taze fasulye düşük enerjili, lif, folat ve K vitamini açısından zengin bir sebzedir. Zeytinyağı, tekli doymamış yağ asitleri sağlar ve domatesteki likopenin emilimini destekler. Tarifin enerjisinin büyük kısmı zeytinyağından geldiğinden, yağ miktarı porsiyon kontrolü gereken bireylerde azaltılabilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~230 kcal"}, {"ad": "Protein", "miktar": "~5 g"}, {"ad": "Yağ", "miktar": "~16 g"}, {"ad": "Karbonhidrat", "miktar": "~22 g"}, {"ad": "Lif", "miktar": "~7 g"}, {"ad": "Şeker", "miktar": "~11 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~920 kcal"}, {"ad": "Protein", "miktar": "~18 g"}, {"ad": "Yağ", "miktar": "~62 g"}, {"ad": "Karbonhidrat", "miktar": "~87 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '2 minutes'
WHERE name = 'Zeytinyağlı Taze Fasulye';
