ezzetli olduğu dönem ekim–şubat aylarıdır.', 'Yanında roka, maydanoz ve yeşil soğanla hazırlanmış limonlu bir salata ile servis edilmesi önerilir. Turp veya lahana turşusu da yemekle iyi uyum sağlar.', 'Hamsi, omega-3 yağ asitleri (EPA ve DHA), yüksek kaliteli protein ve D vitamini açısından değerli bir balıktır; kılçıkla birlikte tüketildiğinde kalsiyum katkısı da artar. Pirinç yemeğin başlıca enerji kaynağıdır. Haftada en az iki kez balık tüketme önerisini karşılamak için uygun bir tariftir; porsiyon kontrolü için salatayla dengelenmelidir.', '[{"ad": "Enerji", "miktar": "~495 kcal"}, {"ad": "Protein", "miktar": "~30 g"}, {"ad": "Yağ", "miktar": "~17 g"}, {"ad": "Karbonhidrat", "miktar": "~53 g"}, {"ad": "Lif", "miktar": "~1 g"}, {"ad": "Şeker", "miktar": "~4 g"}]'::jsonb, '[{"ad": "Enerji", "miktar": "~2960 kcal"}, {"ad": "Protein", "miktar": "~181 g"}, {"ad": "Yağ", "miktar": "~99 g"}, {"ad": "Karbonhidrat", "miktar": "~319 g"}]'::jsonb, NOW() - INTERVAL '3 minutes'
WHERE NOT EXISTS (SELECT 1 FROM public.recipes WHERE name = 'Hamsili Pilav');

-- 5. Kısır
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Salata / Meze',
  duration = '25 dk',
  rating = NULL,
  ingredients = ARRAY['2 su bardağı köftelik ince bulgur', '1,5 su bardağı sıcak su', '1 yemek kaşığı domates salçası', '1 yemek kaşığı biber salçası', '5 yemek kaşığı zeytinyağı', '2 adet orta boy domates', '4 dal yeşil soğan', '1 demet maydanoz', '½ demet taze nane', '2 yemek kaşığı nar ekşisi', '1 adet limonun suyu', '1 çay kaşığı pul biber', '1 çay kaşığı kimyon', '1 çay kaşığı tuz', '8–10 yaprak marul (servis için)']::text[],
  instructions = ARRAY['Bulguru geniş bir kaba alın, sıcak suyu ekleyip karıştırın. Üzerini kapatıp 15 dakika demlendirin.', 'Domates salçası, biber salçası ve zeytinyağını ekleyin. Renk her yere eşit dağılana kadar bulguru elinizle yaklaşık 5 dakika yoğurun.', 'Pul biber, kimyon ve tuzu ekleyip karıştırın, bulguru ılımaya bırakın.', 'Domatesleri küçük küpler halinde doğrayın. Yeşil soğan, maydanoz ve naneyi ince kıyın.', 'Sebzeleri, nar ekşisini ve limon suyunu bulgura ekleyip karıştırın; tadına bakarak ekşiyi ayarlayın.', 'Buzdolabında 30 dakika dinlendirin, marul yapraklarıyla birlikte servis edin.']::text[],
  description = 'Salçalı ince bulgurun bol yeşillik, domates ve nar ekşisiyle karıştırıldığı, pişirme gerektirmeyen ekşili salata',
  region = 'Güneydoğu Anadolu',
  servings = '6 kişilik',
  prep_time = '25 dakika (15 dakika demlenme dahil)',
  cook_time = 'Pişirme gerektirmez (servis öncesi 30 dakika dinlendirme)',
  tips = 'Yeşillikler bulgur ılıdıktan sonra eklenmelidir; sıcak bulgur yeşillikleri soldurur. Kısır bir gün önceden hazırlanabilir, ancak yeşillikleri servis günü eklemek tazeliği korur.',
  nutrition_advice = 'Çay saatinde ara öğün olarak veya ızgara tavuk, balık gibi bir protein kaynağının yanında salata olarak tüketilebilir. Yanında ayran ile servis edilmesi öğünün protein içeriğini artırır.',
  dietitian_note = 'Bulgur, kepeğinin bir kısmını koruyan bir tahıl ürünü olduğundan lif ve B grubu vitaminleri açısından pirince göre daha zengindir. Maydanoz, nane ve limon C vitamini sağlar; bu da bitkisel kaynaklardaki demirin emilimini destekler. Salça ve nar ekşisi tuz içerebileceğinden eklenen tuz miktarı sınırlı tutulmalıdır.',
  nutrition = '[{"ad": "Enerji", "miktar": "~320 kcal"}, {"ad": "Protein", "miktar": "~8 g"}, {"ad": "Yağ", "miktar": "~12 g"}, {"ad": "Karbonhidrat", "miktar": "~49 g"}, {"ad": "Lif", "miktar": "~11 g"}, {"ad": "Şeker", "miktar": "~6 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~1935 kcal"}, {"ad": "Protein", "miktar": "~47 g"}, {"ad": "Yağ", "miktar": "~74 g"}, {"ad": "Karbonhidrat", "miktar": "~294 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '4 minutes'
WHERE name = 'Kısır';
