 tutulmalıdır.', '[{"ad": "Enerji", "miktar": "~320 kcal"}, {"ad": "Protein", "miktar": "~8 g"}, {"ad": "Yağ", "miktar": "~12 g"}, {"ad": "Karbonhidrat", "miktar": "~49 g"}, {"ad": "Lif", "miktar": "~11 g"}, {"ad": "Şeker", "miktar": "~6 g"}]'::jsonb, '[{"ad": "Enerji", "miktar": "~1935 kcal"}, {"ad": "Protein", "miktar": "~47 g"}, {"ad": "Yağ", "miktar": "~74 g"}, {"ad": "Karbonhidrat", "miktar": "~294 g"}]'::jsonb, NOW() - INTERVAL '4 minutes'
