-- 6. Kayseri Mantısı
UPDATE public.recipes SET
  image_url = 'assets/images/kayseri-mantisi.jpg',
  category = 'Ana Yemek',
  duration = '1 sa 45 dk',
  rating = NULL,
  ingredients = ARRAY['Hamur için:', '3 su bardağı un (açmak için ayrıca 2–3 yemek kaşığı)', '1 adet yumurta', '¾ su bardağı ılık su', '1 çay kaşığı tuz', 'İç için:', '250 g orta yağlı dana kıyma', '1 adet küçük boy kuru soğan', '0,5 çay kaşığı tuz', '0,5 çay kaşığı karabiber', 'Sos için:', '2 su bardağı yoğurt', '2 diş sarımsak', '3 yemek kaşığı tereyağı', '1 yemek kaşığı domates salçası', '1 çay kaşığı pul biber', '1 çay kaşığı kuru nane', 'Haşlamak için:', '3 litre su', '1 çay kaşığı tuz']::text[],
  instructions = ARRAY['Un, yumurta, tuz ve ılık suyu yoğurarak ele yapışmayan, kulak memesi kıvamında bir hamur elde edin. Üzerini örtüp 30 dakika dinlendirin.', 'Soğanı rendeleyip suyunu sıkın. Kıyma, soğan, tuz ve karabiberi iyice yoğurun.', 'Hamuru iki bezeye bölün. Unlanmış tezgahta her birini 1–2 mm inceliğinde açın ve 2×2 cm''lik kareler kesin.', 'Her karenin ortasına nohut tanesinden küçük miktarda iç koyun. Dört ucu ortada birleştirip kenarları bastırarak kapatın.', 'Geniş bir tencerede suyu tuzla kaynatın. Mantıları atıp yapışmaması için ara ara karıştırarak hamuru pişene kadar haşlayın (yaklaşık 12 dakika).', 'Mantı haşlanırken sarımsağı ezip oda sıcaklığındaki yoğurtla çırpın.', 'Küçük bir tavada tereyağını eritin, salçayı ekleyip 1 dakika kavurun. Pul biberi ekleyip ocaktan alın.', 'Süzülen mantıları servis tabaklarına paylaştırın. Üzerine sarımsaklı yoğurdu ve sıcak sosu gezdirin, kuru naneyi serperek servis edin.']::text[],
  description = 'İnce açılmış hamurdan küçük bohçalar halinde kapatılan kıymalı mantı; sarımsaklı yoğurt ve tereyağlı salça sosuyla',
  region = 'İç Anadolu – Kayseri',
  servings = '4 kişilik',
  prep_time = '90 dakika (30 dakika hamur dinlendirme dahil)',
  cook_time = '15 dakika',
  tips = 'Kayseri mantısı küçüklüğüyle bilinir; geleneksel olarak bir kaşığa 30–40 mantı sığması beklenir. Kapatılan mantılar unlanmış tepside dondurulup sonra kullanılabilir.',
  nutrition_advice = 'Yanında yeşil salata veya sirkeli bir mevsim salatası ile servis edilmesi öğünü dengeler. Hamur ve yoğurt birlikte yeterince doyurucu olduğundan ayrıca ekmek eklenmemesi önerilir.',
  dietitian_note = 'Mantı, tahıl (hamur), et ve süt grubunu tek tabakta bir araya getiren besleyici bir yemektir. Kıyma demir ve çinko, yoğurt ise kalsiyum ve probiyotik bakteriler sağlar. Tereyağlı sos doymuş yağ içeriğini artırdığından sosun miktarı azaltılabilir veya tereyağının yarısı zeytinyağıyla değiştirilebilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~620 kcal"}, {"ad": "Protein", "miktar": "~26 g"}, {"ad": "Yağ", "miktar": "~23 g"}, {"ad": "Karbonhidrat", "miktar": "~75 g"}, {"ad": "Lif", "miktar": "~3 g"}, {"ad": "Şeker", "miktar": "~6 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~2490 kcal"}, {"ad": "Protein", "miktar": "~104 g"}, {"ad": "Yağ", "miktar": "~93 g"}, {"ad": "Karbonhidrat", "miktar": "~299 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '5 minutes'
WHERE name = 'Kayseri Mantısı';
