WHERE NOT EXISTS (SELECT 1 FROM public.recipes WHERE name = 'Kayseri Mantısı');

-- 7. Menemen
UPDATE public.recipes SET
  image_url = 'assets/images/soganli-menemen.jpg',
  category = 'Kahvaltılık',
  duration = '25 dk',
  rating = NULL,
  ingredients = ARRAY['4 adet yumurta', '3 adet orta boy olgun domates', '3 adet sivri biber', '1 yemek kaşığı tereyağı', '1 yemek kaşığı zeytinyağı', '0,5 çay kaşığı tuz', '0,25 çay kaşığı karabiber', '0,5 çay kaşığı pul biber']::text[],
  instructions = ARRAY['Domateslerin kabuğunu soyup küçük küpler halinde doğrayın. Sivri biberleri ince halkalar halinde kesin.', 'Sahanda veya tavada tereyağı ve zeytinyağını birlikte ısıtın.', 'Biberleri ekleyip yumuşayana kadar orta ateşte 3–4 dakika soteleyin.', 'Domatesleri ve tuzu ekleyin. Domatesler suyunu salıp çekene kadar ara ara karıştırarak pişirin (yaklaşık 8 dakika).', 'Yumurtaları doğrudan tavaya kırın. Birkaç kez yavaşça karıştırıp yumurtalar kıvam alınca altını kapatın (yaklaşık 2 dakika).', 'Karabiber ve pul biber serpip sahanda sıcak servis edin.']::text[],
  description = 'Sivri biber ve domatesin tereyağı ile zeytinyağında pişirilip yumurtayla birleştirildiği sahan yemeği',
  region = 'Ege – İzmir (Menemen ilçesi)',
  servings = '2 kişilik',
  prep_time = '10 dakika',
  cook_time = '15 dakika',
  tips = 'Menemenin sülü kalması için yumurtalar fazla pişirilmemelidir; ocaktan alındıktan sonra sahanın sıcaklığıyla pişmeye devam eder. Soğanlı veya soğansız yapımı yöresel tercihe göre değişir; bu tarif soğansızdır.',
  nutrition_advice = 'Tam tahıllı ekmek, bir dilim beyaz peynir, yeşillik ve birkaç zeytinle dengeli bir kahvaltı oluşturur. Yanında şekersiz çay veya bir bardak ayran tercih edilebilir.',
  dietitian_note = 'Yumurta, tüm temel amino asitleri içeren yüksek biyolojik değerli bir protein kaynağıdır. Domates ve sivri biber C vitamini ve likopen sağlar; pişirme ve yağ varlığı likopenin emilimini artırır. Sabah öğününde protein alımı, gün boyu tokluk ve enerji dengesine katkı sağlar.',
  nutrition = '[{"ad": "Enerji", "miktar": "~295 kcal"}, {"ad": "Protein", "miktar": "~15 g"}, {"ad": "Yağ", "miktar": "~22 g"}, {"ad": "Karbonhidrat", "miktar": "~10 g"}, {"ad": "Lif", "miktar": "~3 g"}, {"ad": "Şeker", "miktar": "~6 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~590 kcal"}, {"ad": "Protein", "miktar": "~29 g"}, {"ad": "Yağ", "miktar": "~45 g"}, {"ad": "Karbonhidrat", "miktar": "~20 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '6 minutes'
WHERE name = 'Menemen';
