-- 8. Tepsi Kebabı
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Ana Yemek',
  duration = '55 dk',
  rating = NULL,
  ingredients = ARRAY['500 g orta yağlı dana kıyma', '1 adet orta boy kuru soğan', '4 adet sivri biber', '1 adet kırmızı kapya biber', '½ demet maydanoz', '1 çay kaşığı tuz', '1 çay kaşığı karabiber', '1 çay kaşığı pul biber', '1 çay kaşığı kimyon', '2 adet orta boy domates', '1 yemek kaşığı domates salçası', '1 yemek kaşığı biber salçası', '1 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su']::text[],
  instructions = ARRAY['Fırını 200°C''ye ısıtın.', 'Soğanı, 2 adet sivri biberi, kapya biberi ve maydanozu çok ince kıyın. Sebzelerin suyunu hafifçe sıkın.', 'Kıymayı kıyılmış sebzeler, tuz, karabiber, pul biber ve kimyonla birlikte yaklaşık 5 dakika yoğurun.', 'Harcı 28–30 cm''lik yuvarlak bir tepsiye 1–1,5 cm kalınlığında eşit olarak yayın. Bıçakla dilim çizgileri çizin.', 'Domatesleri halka halinde, kalan 2 sivri biberi boyuna ikiye kesip kıymanın üzerine dizin.', 'Domates salçası, biber salçası, zeytinyağı ve sıcak suyu karıştırıp tepsinin her yerine gezdirin.', 'Kıyma pişip sos koyulaşana kadar fırında pişirin (yaklaşık 35 dakika).', '5 dakika dinlendirin, çizdiğiniz yerlerden dilimleyerek servis edin.']::text[],
  description = 'Sebzelerle yoğrulan kıymanın tepsiye yayılıp domates, biber ve salçalı sosla fırında pişirildiği kebap',
  region = 'Akdeniz – Hatay',
  servings = '4 kişilik',
  prep_time = '20 dakika',
  cook_time = '35 dakika',
  tips = 'Geleneksel tarifte kıyma ve sebzeler zırh (iki saplı, kavisli bıçak) ile birlikte kıyılır ve tepsi fırında pişirilir. Kıyma olarak dana ve kuzu karışımı da kullanılabilir.',
  nutrition_advice = 'Yanında bulgur pilavı veya tam buğday lavaş, ayran ve soğanlı sumaklı bir salata ile servis edilebilir. Pilav eklenirse porsiyon miktarı küçük tutulmalıdır.',
  dietitian_note = 'Kırmızı et, iyi emilen hem demiri, çinko ve B12 vitamini açısından zengindir. Tarif, fırında pişirildiği ve kızartma içermediği için eklenen yağ miktarı düşüktür; yağın büyük kısmı kıymadan gelir. Yağsız kıyma tercih edilerek doymuş yağ ve enerji değeri azaltılabilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~345 kcal"}, {"ad": "Protein", "miktar": "~25 g"}, {"ad": "Yağ", "miktar": "~22 g"}, {"ad": "Karbonhidrat", "miktar": "~10 g"}, {"ad": "Lif", "miktar": "~3 g"}, {"ad": "Şeker", "miktar": "~5 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~1390 kcal"}, {"ad": "Protein", "miktar": "~100 g"}, {"ad": "Yağ", "miktar": "~90 g"}, {"ad": "Karbonhidrat", "miktar": "~39 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '7 minutes'
WHERE name = 'Tepsi Kebabı';
