-- 9. Ayran Aşı Çorbası
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Çorba',
  duration = '1 sa 15 dk',
  rating = NULL,
  ingredients = ARRAY['½ su bardağı aşurelik buğday', '½ su bardağı haşlanmış nohut', '3 su bardağı yoğurt', '1 adet yumurta', '2 yemek kaşığı un', '6 su bardağı su', '1 çay kaşığı tuz', '2 yemek kaşığı tereyağı', '1 yemek kaşığı kuru nane']::text[],
  instructions = ARRAY['Buğdayı bir gece önceden bol suda ıslatın. Pişirmeden önce süzün.', 'Buğdayı 6 su bardağı suyla tencereye alın. Kapağı kapalı, kısık ateşte taneler yumuşayana kadar pişirin (yaklaşık 40 dakika).', 'Haşlanmış nohudu ekleyip 5 dakika daha pişirin.', 'Ayrı bir kapta yoğurt, yumurta ve unu pürüzsüz olana kadar çırpın.', 'Tencereden bir kepçe sıcak suyu terbiyeye azar azar ekleyerek ılıştırın. Ardından terbiyeyi sürekli karıştırarak tencereye dökün.', 'Çorba kaynayana kadar aynı yöne karıştırmaya devam edin. Kaynayınca altını kısıp 10 dakika pişirin ve tuzu ekleyin.', 'Tereyağını küçük bir tavada eritin, kuru naneyi ekleyip 30 saniye kızdırın. Servis sırasında çorbanın üzerine gezdirin.']::text[],
  description = 'Buğday ve nohutla pişirilen, yoğurt terbiyeli ve tereyağlı naneli sıcak çorba',
  region = 'Doğu Anadolu – Erzurum',
  servings = '6 kişilik',
  prep_time = '15 dakika (buğday bir gece önceden ıslatılır)',
  cook_time = '60 dakika',
  tips = 'Yoğurdun kesilmemesi için terbiye mutlaka ılıştırılmalı ve tuz en son eklenmelidir. Buğday yerine aynı miktarda pirinç kullanılabilir; bu durumda pişirme süresi yaklaşık 20 dakikaya iner.',
  nutrition_advice = 'Yanında tam tahıllı ekmek ve bir porsiyon sebze yemeği ile hafif bir öğün oluşturur. Et veya köfte yemeklerinden önce başlangıç çorbası olarak da servis edilebilir.',
  dietitian_note = 'Yoğurt kalsiyum, protein ve probiyotik bakteriler; buğday ve nohut ise lif ve bitkisel protein sağlar. Tahıl, baklagil ve süt grubunun bir arada bulunması çorbayı tek başına doyurucu kılar. Doymuş yağı azaltmak için tereyağı miktarı düşürülebilir veya nane zeytinyağında kızdırılabilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~190 kcal"}, {"ad": "Protein", "miktar": "~8 g"}, {"ad": "Yağ", "miktar": "~9 g"}, {"ad": "Karbonhidrat", "miktar": "~22 g"}, {"ad": "Lif", "miktar": "~3 g"}, {"ad": "Şeker", "miktar": "~5 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~1155 kcal"}, {"ad": "Protein", "miktar": "~47 g"}, {"ad": "Yağ", "miktar": "~52 g"}, {"ad": "Karbonhidrat", "miktar": "~130 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '8 minutes'
WHERE name = 'Ayran Aşı Çorbası';
