-- 10. Fırın Sütlaç
UPDATE public.recipes SET
  image_url = NULL,
  category = 'Tatlı',
  duration = '1 sa',
  rating = NULL,
  ingredients = ARRAY['½ su bardağı pirinç', '1,5 su bardağı su', '1 litre tam yağlı süt', '¾ su bardağı toz şeker', '3 yemek kaşığı pirinç unu', '1 paket vanilin', 'Tarçın (servis için, isteğe bağlı)']::text[],
  instructions = ARRAY['Pirinci yıkayıp suyla birlikte tencereye alın. Suyunu çekip yumuşayana kadar kısık ateşte haşlayın (yaklaşık 15 dakika).', 'Sütün yarım su bardağını ayırın. Kalan sütü pirince ekleyip kaynayana kadar karıştırarak pişirin.', 'Şekeri ekleyin, kısık ateşte ara ara karıştırarak 10 dakika pişirin.', 'Ayırdığınız soğuk sütte pirinç ununu pürüzsüz olana kadar açın. Tencereye azar azar ekleyip sürekli karıştırarak koyulaşana kadar pişirin (yaklaşık 5 dakika).', 'Vanilini ekleyip ocaktan alın. Karışımı fırına dayanıklı kaselere paylaştırın.', 'Fırını 200°C''ye ısıtın. Kaseleri, kaselerin yarısına kadar soğuk su doldurulmuş bir fırın tepsisine dizin.', 'Tepsiyi fırının üst rafına yerleştirin ve sütlaçların üstü kızarana kadar pişirin (yaklaşık 20 dakika).', 'Oda sıcaklığına gelince buzdolabında en az 2 saat soğutun. İsterseniz tarçın serperek servis edin.']::text[],
  description = 'Sütte pişirilen pirincin pirinç unuyla koyulaştırılıp fırında üstü kızartıldığı, soğuk servis edilen sütlü tatlı',
  region = 'Türk mutfağı (ülke geneli)',
  servings = '6 kişilik',
  prep_time = '10 dakika',
  cook_time = '50 dakika (servis öncesi en az 2 saat soğutma)',
  tips = 'Tepsideki su, sütlaçların alttan taşmasını ve kesilmesini önler; üst yüzeyin kızarması için fırının üst ısıtıcısı kullanılabilir. Pirinç unu yerine aynı miktarda buğday nişastası kullanılabilir.',
  nutrition_advice = 'Tatlı ihtiyacını karşılamak için ana öğünden hemen sonra değil, ara öğünde tüketilmesi önerilir. Üzerine eklenen bir avuç ceviz veya fındık içi, sağlıklı yağ ve protein katkısını artırır.',
  dietitian_note = 'Süt bazlı tatlılar, şerbetli tatlılara göre daha düşük yağ ve enerji içerir; ayrıca kalsiyum ve protein sağlar. Ancak eklenen şeker nedeniyle porsiyon başına şeker miktarı yüksektir. Şeker miktarı ½ su bardağına indirilerek tat dengesi büyük ölçüde korunurken şeker alımı azaltılabilir.',
  nutrition = '[{"ad": "Enerji", "miktar": "~275 kcal"}, {"ad": "Protein", "miktar": "~7 g"}, {"ad": "Yağ", "miktar": "~6 g"}, {"ad": "Karbonhidrat", "miktar": "~48 g"}, {"ad": "Lif", "miktar": "<1 g"}, {"ad": "Şeker", "miktar": "~32 g"}]'::jsonb,
  nutrition_total = '[{"ad": "Enerji", "miktar": "~1645 kcal"}, {"ad": "Protein", "miktar": "~41 g"}, {"ad": "Yağ", "miktar": "~34 g"}, {"ad": "Karbonhidrat", "miktar": "~290 g"}]'::jsonb,
  created_at = NOW() - INTERVAL '9 minutes'
WHERE name = 'Fırın Sütlaç';
